#!/usr/bin/env python3
"""Zweisprachige Schreibpraxis-Übersicht lokal erzeugen; kein Upload."""
from pathlib import Path
from html import escape

ROOT = Path(__file__).resolve().parents[1]
STYLE = '''
:root{--ink:#183438;--muted:#526a6d;--orange:#f07f2e;--accent:#b9551d;--line:#cedbd5}*{box-sizing:border-box}body{margin:0;background:#fbfaf6;color:var(--ink);font:18px/1.7 system-ui,sans-serif}header,main,footer{max-width:1120px;margin:auto;padding:24px 40px}header{display:flex;align-items:center;justify-content:space-between;gap:20px;border-bottom:3px solid var(--orange)}a{color:var(--accent);text-underline-offset:4px}a:focus-visible{outline:3px solid var(--accent);outline-offset:5px}.brand{display:flex;align-items:center;gap:12px;text-decoration:none;color:var(--ink);font-weight:750}.brand img{width:48px;height:48px}.brand small{display:block;font-size:12px;font-weight:500;color:var(--muted)}h1{font:normal clamp(40px,5vw,62px)/1.15 Georgia,serif;margin:40px 0 20px}.lead{max-width:760px;font-size:21px;color:var(--muted);margin-bottom:38px}.tiles{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:26px}.tile{display:flex;flex-direction:column;text-decoration:none;color:var(--ink);border:1px solid var(--line);border-radius:12px;overflow:hidden;background:#fffefa;transition:transform .15s,box-shadow .15s}.tile:hover{transform:translateY(-3px);box-shadow:0 8px 24px #18343812}.art{height:180px;display:flex;align-items:center;justify-content:center;background:#fff0df;border-bottom:3px solid var(--orange)}.art svg{width:180px;height:130px}.copy{padding:28px;display:flex;flex:1;flex-direction:column}.tag{font-size:12px;letter-spacing:.08em;text-transform:uppercase;color:var(--accent)}h2{font:normal 31px/1.2 Georgia,serif;margin:14px 0}.copy p{margin:0 0 24px;color:var(--muted);font-size:16px}.open{margin-top:auto;color:var(--accent);font-weight:650;font-size:15px}footer{margin-top:40px;border-top:1px solid var(--line);font-size:12px;color:var(--muted)}footer p{margin:6px 0}@media(max-width:700px){header,main,footer{padding:20px}.tiles{grid-template-columns:1fr}h1{margin-top:24px}.art{height:140px}.copy{padding:24px}}@media(prefers-reduced-motion:reduce){.tile{transition:none}}@media print{.tiles{display:block}.tile{break-inside:avoid;margin-bottom:24px}.art{display:none}}
'''
ICONS = [
    '<svg viewBox="0 0 180 130" fill="none" aria-hidden="true"><path d="M90 108c-18-14-39-17-63-13V25c25-5 46 0 63 13 17-13 38-18 63-13v70c-24-4-45-1-63 13Z" fill="#fffefa" stroke="#183438" stroke-width="3"/><path d="M90 38v70M41 44c12 0 23 3 33 8M41 60c12 0 23 3 33 8M106 52l12 12 27-31" stroke="#b9551d" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/></svg>',
    '<svg viewBox="0 0 180 130" fill="none" aria-hidden="true"><rect x="20" y="20" width="84" height="56" rx="12" stroke="#b9551d" stroke-width="3"/><path d="M38 76v16l19-16M38 39h46M38 53h32" stroke="#b9551d" stroke-width="3" stroke-linecap="round"/><rect x="105" y="48" width="50" height="64" rx="5" fill="#fffefa" stroke="#183438" stroke-width="3"/><path d="M115 64h30M115 76h30M115 88h20" stroke="#183438" stroke-width="3" stroke-linecap="round"/></svg>',
    '<svg viewBox="0 0 180 130" fill="none" aria-hidden="true"><rect x="17" y="15" width="42" height="36" rx="8" stroke="#b9551d" stroke-width="3"/><rect x="69" y="15" width="42" height="36" rx="8" stroke="#b9551d" stroke-width="3"/><rect x="121" y="15" width="42" height="36" rx="8" stroke="#b9551d" stroke-width="3"/><path d="M38 52v16h104V52M90 52v27" stroke="#b9551d" stroke-width="3"/><rect x="62" y="82" width="56" height="36" rx="5" fill="#fffefa" stroke="#183438" stroke-width="3"/><path d="m63 84 27 20 27-20" stroke="#183438" stroke-width="3"/></svg>',
    '<svg viewBox="0 0 180 130" fill="none" aria-hidden="true"><rect x="24" y="17" width="75" height="94" rx="5" fill="#fffefa" stroke="#183438" stroke-width="3"/><path d="M39 36h44M39 50h34M39 64h27" stroke="#183438" stroke-width="3" stroke-linecap="round"/><circle cx="112" cy="70" r="25" fill="#fffefa" stroke="#b9551d" stroke-width="4"/><path d="m130 89 24 24m-54-43 8 8 16-19" stroke="#b9551d" stroke-width="4" stroke-linecap="round" stroke-linejoin="round"/></svg>',
    '<svg viewBox="0 0 180 130" fill="none" aria-hidden="true"><path d="M90 108c-18-14-39-17-63-13V25c25-5 46 0 63 13 17-13 38-18 63-13v70c-24-4-45-1-63 13Z" fill="#fffefa" stroke="#183438" stroke-width="3"/><path d="M90 38v70M42 49h12v15H42zm23 0h12v15H65zM108 53h29M108 68h29M108 83h19" stroke="#b9551d" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/></svg>',
]
for lang,suffix in [('de',''),('en','.en')]:
    en=lang=='en'
    series='Writing practice' if en else 'Schreibpraxis'
    other='schreibpraxis.html' if en else 'schreibpraxis.en.html'
    other_label='Deutsch' if en else 'English'
    home='index'+suffix+'.html'
    title='See how a text takes shape' if en else 'So entsteht ein Text'
    lead='Explore how conversation, drafts, research and human judgement work together in GhostWriter.' if en else 'Erlebe, wie Gespräch, Entwurf, Recherche und menschliches Urteil beim Schreiben mit GhostWriter zusammenwirken.'
    entries=[
        ('buchentwicklung/index'+suffix+'.html', 'An idea becomes a crime novel' if en else 'Aus einer Idee wird ein Krimi', 'Developing a book · simulated dialogue' if en else 'Ein Buch entwickeln · simulierter Dialog', '“I want to write a book.” Follow how answers lead to new questions and a crime novel takes shape: setting, characters, plot and narrative voice.' if en else '„Ich möchte ein Buch schreiben.“ Erlebe, wie Antworten zu neuen Fragen führen und ein Krimi Gestalt annimmt: Ort, Figuren, Handlung und Erzählweise.'),
        ('schreibpraxis/index'+suffix+'.html', 'From conversation to your own text' if en else 'Vom Gespräch zum eigenen Text', 'Based on a real writing process' if en else 'Aus einem tatsächlichen Arbeitsverlauf', 'How memories become a chapter, additional material joins the draft and feedback shapes the narrative voice. Personal content is abstracted; dialogue examples are fictional.' if en else 'Wie aus Erinnerungen ein Kapitel wird, zusätzlicher Text hinzukommt und Rückmeldungen die Erzählstimme verändern. Persönliche Inhalte sind abstrahiert, Dialogbeispiele erfunden.'),
        ('augmentiert/index'+suffix+'.html', 'Augmented work' if en else 'Augmentiert arbeiten', 'Entirely simulated example' if en else 'Vollständig simuliertes Beispiel', 'One letter, three writing dialogues: follow the questions, compare the drafts and see what the person selects, rejects and revises. No provider ranking.' if en else 'Ein Brief, drei Schreibdialoge: Fragen verfolgen, Entwürfe vergleichen und sehen, was der Mensch auswählt, verwirft und überarbeitet. Kein Anbieter-Ranking.'),
        ('recherche/index'+suffix+'.html', 'Is that right? – Putting a claim to the test' if en else 'Stimmt das so? – Eine Behauptung auf dem Prüfstand', 'Research · simulated dialogue' if en else 'Recherche · simulierter Dialog', 'Check an earthquake claim, assess what an expert source supports and follow the author’s decision on a reasoned revision. The dialogue is fictional; the linked expert source is real.' if en else 'Eine Erdbebenbehauptung prüfen, die Aussagekraft einer Fachquelle beurteilen und einen begründeten Änderungsvorschlag mit dem Autor abstimmen. Der Dialog ist erfunden, die verlinkte Fachquelle real.'),
        ('zitieren/index'+suffix+'.html', 'Haven’t we researched this before? – Finding your earlier work and citing it clearly' if en else 'Das habe ich doch schon recherchiert – Eigenes wiederfinden und richtig zitieren', 'References · simulated dialogue' if en else 'Belegen · simulierter Dialog', 'Find earlier research and distinguish a reference to your own book from expert evidence, a quotation and a paraphrase. Dialogue and book findings are fictional; gaps in the sources remain visible.' if en else 'Frühere Recherche wiederfinden und zwischen Eigenverweis, Fachbeleg, Zitat und sinngemäßer Wiedergabe unterscheiden. Gespräch und Buchfunde sind erfunden; Quellenlücken bleiben sichtbar.'),
    ]
    cards=''.join(f'<a class="tile" href="{url}"><div class="art">{ICONS[i]}</div><div class="copy"><span class="tag">{escape(tag)}</span><h2>{escape(heading)}</h2><p>{escape(desc)}</p><span class="open">{"Explore the walkthrough" if en else "Seitenstrecke öffnen"} →</span></div></a>' for i,(url,heading,tag,desc) in enumerate(entries))
    credit='Developed with support from' if en else 'Entwickelt mit Unterstützung von'
    page=f'''<!doctype html><html lang="{lang}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{series} · GhostWriter</title><link rel="alternate" hreflang="{'de' if en else 'en'}" href="{other}"><style>{STYLE}</style></head><body><header><a class="brand" href="{home}"><img src="assets/logo.svg" alt="" width="48" height="48"><span>GhostWriter<small>{series}</small></span></a><a href="{other}" lang="{'de' if en else 'en'}">{other_label}</a></header><main><h1>{title}</h1><p class="lead">{lead}</p><nav class="tiles" aria-label="{'Writing walkthroughs' if en else 'Seitenstrecken zum Schreiben'}">{cards}</nav></main><footer><p><a href="{home}">{'GhostWriter home' if en else 'GhostWriter-Startseite'}</a></p><p>{credit} Claude (Anthropic)<br>{credit} Codex (OpenAI)</p></footer></body></html>'''
    (ROOT/'website'/('schreibpraxis'+suffix+'.html')).write_text(page+'\n',encoding='utf-8')
print('Schreibpraxis-Übersicht Deutsch/Englisch lokal erzeugt; kein Upload.')
